/* From Uiverse.io by xopc333 - Tags: animation, minimalist, card, creative, border, hover effect, css effect, card template */
.__UIV_SCOPE__ .card {
  position: relative;
  display: flex;
  width: 200px;
  height: 320px;
  background: #C6C6D0;
  color: #212121;
  box-shadow: inset 0 0 0 4px #212121;
  transition: .6s 0.4s;
  cursor: pointer;
}

.__UIV_SCOPE__ .border {
  position: absolute;
  inset: 0;
}

.__UIV_SCOPE__ .border line {
  stroke-width: 4px;
  stroke: #C6C6D0;
  fill: none;
  transition: .6s ease-in-out;
}

.__UIV_SCOPE__ .border line.top,
.__UIV_SCOPE__ .border line.bottom {
  stroke-dasharray: 200;
}

.__UIV_SCOPE__ .border line.left,
.__UIV_SCOPE__ .border line.right {
  stroke-dasharray: 320;
}

.__UIV_SCOPE__ .logo {
  width: 50%;
  margin: auto;
  fill: #212121;
  transition: .6s;
  opacity: 0.9;
}

.__UIV_SCOPE__ .card:hover {
  background-color: transparent;
  transition-delay: 0s;
}

.__UIV_SCOPE__ .card:hover .border line {
  transition-delay: 0.1s;
}

.__UIV_SCOPE__ .card:hover .border line.top {
  transform: translateX(-400px);
}

.__UIV_SCOPE__ .card:hover .border line.bottom {
  transform: translateX(400px);
}

.__UIV_SCOPE__ .card:hover .border line.left {
  transform: translateY(640px);
}

.__UIV_SCOPE__ .card:hover .border line.right {
  transform: translateY(-640px);
}

.__UIV_SCOPE__ .card:hover .logo {
  transition-delay: 0s;
  transform: scale(1.1);
  fill: #C6C6D0;
  filter: drop-shadow( 0 0 30px #C6C6D080);
  opacity: 0.9;
}
